# -*- coding: utf-8 -*-
"""test_v3_properties.py — Phase F·G03：Hypothesis 属性测试（决策树+三态迁移+账本链）。"""
import json
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))

from hypothesis import given, settings, strategies as st, HealthCheck  # noqa: E402
from cbb2.store import Store  # noqa: E402
from cbb2.ledger import LedgedStore, line_hash  # noqa: E402

record_strategy = st.fixed_dictionaries({
    "record_id": st.text(min_size=1, max_size=12).filter(lambda s: s.isalnum()),
    "record_type": st.sampled_from(["entity", "relation", "event"]),
    "library": st.sampled_from(["character", "relation", "event"]),
    "status": st.just("provisional"),
    "canonical": st.fixed_dictionaries({
        "name": st.text(min_size=1, max_size=8).filter(lambda s: s.isprintable()),
        "entity_type": st.sampled_from(["人物", "组织", "地点"]),
        "status": st.sampled_from(["alive", "dead", "missing"]),
    }),
    "evidence": st.lists(st.fixed_dictionaries({
        "vol": st.just(1), "chapter": st.integers(1, 100), "line": st.integers(1, 200),
        "quote": st.text(min_size=1, max_size=20),
    }), min_size=1, max_size=3),
    "provenance": st.fixed_dictionaries({"extractor_confidence": st.integers(60, 95)}),
    "version": st.just(1), "supersedes": st.none(),
    "verified_against": st.fixed_dictionaries({
        "path": st.just("t"), "sha": st.just("a" * 7), "verified_at": st.just("2000-01-01")}),
})

entry_strategy = st.fixed_dictionaries({
    "seq": st.integers(1, 1000),
    "op": st.just("append"),
    "target": st.sampled_from(["libraries/character/provisional", "quarantine-zone/items.jsonl"]),
    "idempotency_key": st.text(min_size=1, max_size=10).filter(lambda s: s.isalnum()),
    "sha_before": st.text(min_size=64, max_size=64),
    "sha_after": st.text(min_size=64, max_size=64),
    "prev_hash": st.text(min_size=64, max_size=64),
    "hash": st.text(min_size=64, max_size=64),
})


class TestWriteDecisionProperties:
    def setup_method(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.store = Store(Path(self.tmp.name))

    def teardown_method(self):
        self.tmp.cleanup()

    @given(rec=record_strategy, at=st.sampled_from(["ch0014", "ch0020", "ch0050"]))
    @settings(max_examples=30, suppress_health_check=[HealthCheck.too_slow, HealthCheck.function_scoped_fixture])
    def test_total(self, rec, at):
        out = self.store.write_decision(rec, at=at, register_conflict=False)
        assert out["track"] in (
            "on-create", "consistent-duplicate", "complementary-statement",
            "invalidation-update", "uncertain-coexist", "contradiction")

    def test_idempotent(self, rec, at):
        pass


class TestLedgerChainProperties:
    @given(entries=st.lists(entry_strategy, max_size=30))
    @settings(max_examples=30, suppress_health_check=[HealthCheck.too_slow, HealthCheck.data_too_large, HealthCheck.filter_too_much])
    def test_chain_recompute(self, entries):
        ls = LedgedStore(Path(tempfile.mkdtemp()))
        for e in entries:
            ls.ledger.record_append(e["target"], e["idempotency_key"], e["sha_before"], e["sha_after"])
        v = ls.ledger.verify()
        assert v["ok"]


if __name__ == "__main__":
    print("run via pytest for class-based tests")
